package mx.com.mesaregia.ordenes.integration.event; import com.fasterxml.jackson.databind.ObjectMapper; import mx.com.mesaregia.ordenes.domain.entity.IntegrationOutbox; import mx.com.mesaregia.ordenes.repository.IntegrationOutboxRepository; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.util.UUID; @Component public class LoggingDomainEventPublisher implements DomainEventPublisher {private final IntegrationOutboxRepository repo;private final ObjectMapper json;public LoggingDomainEventPublisher(IntegrationOutboxRepository r,ObjectMapper j){repo=r;json=j;}@Override @Transactional public void publish(OrdenEstadoCambiadoEvent event){try{var e=new IntegrationOutbox();e.setEventId(UUID.randomUUID().toString());e.setTipo("ORDEN_ESTADO_CAMBIADO");e.setPayload(json.writeValueAsString(event));repo.save(e);}catch(Exception ex){throw new IllegalStateException("No fue posible persistir evento de Orden",ex);}}}